theorem lg_target {n a : ℕ} : (∃ x, x ^ n = a) ↔ n = 0 ∧ a = 1 ∨ n ≠ 0 ∧ n.nthRoot a ^ n = a := by
  cases n
  case zero => 
    split
    { intro h
      rw [pow_zero] at h
      exact ⟨1, h⟩ }
    { rintro (h1 | h2)
      { exact false.elim h1 }
      { rcases h2 with (h3 | h4)
        { exact false.elim h3 }
        { exact h4 } } }
  case (succ n) =>
    split
    { intro h
      refine ⟨n.nthRoot a, _⟩
      rw [h, n.nthRoot_pow_self] }
    { rintro (h1 | h2)
      { exact false.elim h1 }
      { rcases h2 with (h3 | h4)
        { exact false.elim h3 }
        { exact h4 } } }
